public class RoutingServiceOperations {
  private final Graph graph;
  private final GraphIndex graphIndex;
  private final RoutingServiceQueryHelper queryHelper;

  public RoutingServiceOperations(Graph graph) {
    this.graph = graph;
    this.graphIndex = graph.index;
    this.queryHelper = new RoutingServiceQueryHelper(graph);
  }

  public RoutingResponse route(RoutingRequest request, Router router) {
    return new RoutingWorker(router, request, graph.getTimeZone().toZoneId()).route();
  }

  public List<StopTimesInPattern> stopTimesForStop(StopLocation stop, long startTime, int timeRange, int numberOfDepartures, ArrivalDeparture arrivalDeparture, boolean includeCancelledTrips, RoutingService service) {
    return queryHelper.stopTimesForStop(service, stop, startTime, timeRange, numberOfDepartures, arrivalDeparture, includeCancelledTrips);
  }

  public List<StopTimesInPattern> getStopTimesForStop(StopLocation stop, ServiceDate serviceDate, ArrivalDeparture arrivalDeparture, RoutingService service) {
    return queryHelper.getStopTimesForStop(service, stop, serviceDate, arrivalDeparture);
  }

  public List<TripTimeOnDate> stopTimesForPatternAtStop(StopLocation stop, TripPattern pattern, long startTime, int timeRange, int numberOfDepartures, ArrivalDeparture arrivalDeparture, RoutingService service) {
    return queryHelper.stopTimesForPatternAtStop(service, stop, pattern, startTime, timeRange, numberOfDepartures, arrivalDeparture);
  }

  public Collection<TripPattern> getPatternsForStop(StopLocation stop, boolean includeRealtimeUpdates, RoutingService service) {
    return graphIndex.getPatternsForStop(stop, includeRealtimeUpdates ? service.getTimetableSnapshotForQuery() : null);
  }

  public Collection<TripPattern> getPatternsForStop(StopLocation stop) { return graphIndex.getPatternsForStop(stop); }
  public Collection<TripPattern> getPatternsForStop(StopLocation stop, TimetableSnapshot snapshot) { return graphIndex.getPatternsForStop(stop, snapshot); }
  public Agency getAgencyForId(FeedScopedId id) { return graphIndex.getAgencyForId(id); }
  public StopLocation getStopForId(FeedScopedId id) { return graphIndex.getStopForId(id); }
  public Route getRouteForId(FeedScopedId id) { return graphIndex.getRouteForId(id); }
  public void addRoutes(Route route) { graphIndex.addRoutes(route); }
  public Set<Route> getRoutesForStop(StopLocation stop) { return graphIndex.getRoutesForStop(stop); }
  public Collection<Operator> getAllOperators() { return graphIndex.getAllOperators(); }
  public Map<FeedScopedId, Operator> getOperatorForId() { return graphIndex.getOperatorForId(); }
  public Collection<StopLocation> getAllStops() { return graphIndex.getAllStops(); }
  public Map<FeedScopedId, Trip> getTripForId() { return graphIndex.getTripForId(); }
  public Collection<Route> getAllRoutes() { return graphIndex.getAllRoutes(); }
  public Map<Stop, org.opentripplanner.routing.vertextype.TransitStopVertex> getStopVertexForStop() { return graphIndex.getStopVertexForStop(); }
  public Map<Trip, TripPattern> getPatternForTrip() { return graphIndex.getPatternForTrip(); }
  public Multimap<String, TripPattern> getPatternsForFeedId() { return graphIndex.getPatternsForFeedId(); }
  public Multimap<Route, TripPattern> getPatternsForRoute() { return graphIndex.getPatternsForRoute(); }
  public Map<org.opentripplanner.model.Station, MultiModalStation> getMultiModalStationForStations() { return graphIndex.getMultiModalStationForStations(); }
  public HashGridSpatialIndex<org.opentripplanner.routing.vertextype.TransitStopVertex> getStopSpatialIndex() { return graphIndex.getStopSpatialIndex(); }
  public Map<ServiceDate, TIntSet> getServiceCodesRunningForDate() { return graphIndex.getServiceCodesRunningForDate(); }
  public FlexIndex getFlexIndex() { return graphIndex.getFlexIndex(); }

  public List<NearbyStop> findClosestStops(double lat, double lon, double radiusMeters) { return queryHelper.findClosestStops(lat, lon, radiusMeters); }

  public List<PlaceAtDistance> findClosestPlaces(double lat, double lon, double radiusMeters, int maxResults, List<TransitMode> filterByModes, List<PlaceType> filterByPlaceTypes, List<FeedScopedId> filterByStops, List<FeedScopedId> filterByRoutes, List<String> filterByBikeRentalStations, List<String> filterByBikeParks, List<String> filterByCarParks, RoutingService service) {
    return queryHelper.findClosestPlaces(lat, lon, radiusMeters, maxResults, filterByModes, filterByPlaceTypes, filterByStops, filterByRoutes, filterByBikeRentalStations, filterByBikeParks, filterByCarParks, service);
  }

  public TripOnServiceDate getTripOnServiceDateForTripAndDay(FeedScopedId tripId, ServiceDate serviceDate, RoutingService service) { return queryHelper.getTripOnServiceDateForTripAndDay(service, tripId, serviceDate); }
  public TripOnServiceDate getTripOnServiceDateById(FeedScopedId id, RoutingService service) { return queryHelper.getTripOnServiceDateById(service, id); }
  public Map<TripIdAndServiceDate, TripOnServiceDate> getTripOnServiceDateForTripAndDay() { return graphIndex.getTripOnServiceDateForTripAndDay(); }
  public Map<FeedScopedId, TripOnServiceDate> getTripOnServiceDateById() { return graphIndex.getTripOnServiceDateById(); }
